import sys
import string

# Configuration
MIN_LEN = 20
INFILE = '/home/ctfplayer/ctf_files/thoroughlyStripped'


def scan_ascii_runs(filename, min_len):
    results = []
    with open(filename, 'rb') as f:
        data = f.read()
    current_offset = None
    current_run = b''
    for i, b in enumerate(data):
        if chr(b) in string.printable and b != 0x0a and b != 0x0d:
            if current_offset is None:
                current_offset = i
            current_run += bytes([b])
        else:
            if len(current_run) >= min_len:
                results.append((current_offset, current_run.decode('ascii')))
            current_run = b''
            current_offset = None
    if current_run and len(current_run) >= min_len:
        results.append((current_offset, current_run.decode('ascii')))
    return results

def main():
    runs = scan_ascii_runs(INFILE, MIN_LEN)
    for offset, s in runs:
        print(f'O@{offset:08X}: {s}')

if __name__ == '__main__':
    main()

import binascii
import re

with open('/tmp/thoroughlyStripped.hex','r') as f:
