    bindata = binascii.unhexlify(hexdata)

flag_regex = re.compile(b'(flag\{[^\}\r\n]{5,80}\})')
# Try all 0-255 XOR
for x in range(256):
    decoded = bytes(b ^ x for b in bindata)
    match = flag_regex.search(decoded)
