        print(f"XOR 0x{x:02X}: {match.group(1)}")
# Try ROT13 alpha (A-Za-z)
def rot13(data):
    out = bytearray()
    for b in data:
        if 65 <= b <= 90:
            out.append((b-65+13)%26+65)
        elif 97 <= b <= 122:
            out.append((b-97+13)%26+97)
        else:
            out.append(b)
    return bytes(out)
rot = rot13(bindata)
match = flag_regex.search(rot)
if match:
    print(f"ROT13: {match.group(1)}")
# Also search for reversed flag
revflag = re.compile(b'(\}[^{\r\n]{5,80}gat)')
for m in revflag.finditer(bindata):
    print(f"Reversed candidate: {m.group(1)[::-1]}")

import sys
import binascii
import string
from collections import defaultdict

def xor_bytes(data, xor_val):
    return bytes([b ^ xor_val for b in data])

def find_flag_patterns(data, patterns):
    found = []
    # Search for exact matches
    for pat in patterns:
        idx = 0
        while True:
            idx = data.find(pat, idx)
            if idx == -1:
                break
            found.append((idx, pat, 'plain'))
            idx += 1
    return found

def rot_bytes(data, rot_val):
    # ROT : just shift byte circularly
    return bytes([(b + rot_val) % 256 for b in data])

def reversed_patterns(patterns):
    return [pat[::-1] for pat in patterns]

fn = '/home/ctfplayer/ctf_files/thoroughlyStripped'
with open(fn, 'rb') as f:
    alldata = f.read()

# Find non-printable bytes blocks
nonprint_blocks = []
curr = bytearray()
for b in alldata:
    if chr(b) not in string.printable:
        curr.append(b)
    else:
        if curr:
            nonprint_blocks.append(bytes(curr))
            curr = bytearray()
if curr:
    nonprint_blocks.append(bytes(curr))

# Patterns to check (and reversed)
flag_patterns = [b'flag{', b'}galf']
flag_patterns += reversed_patterns(flag_patterns)
results = []
xorvals = [1,2,0x20,0x80,0xff]
rots = set(range(1,26))
for block in nonprint_blocks:
    # Direct/plain pattern scan
    results += find_flag_patterns(block, flag_patterns)

    # XOR
    for x in xorvals:
        xblock = xor_bytes(block, x)
        results += find_flag_patterns(xblock, flag_patterns)

    # ROT
    for r in rots:
        rblock = rot_bytes(block, r)
        results += find_flag_patterns(rblock, flag_patterns)

# Output findings: index, pattern, method, contextual bytes
