    print('Context:', binascii.hexlify(context))

# Try to reconstruct ASCII flag-like contents from blocks
possible_flags = []
for block in nonprint_blocks:
    for i in range(len(block)):
        for j in range(i+7, min(i+60,len(block))): # potential flag length
            frag = block[i:j]
            if b'flag{' in frag or b'}galf' in frag or (frag and frag[0] == ord('f') and b'}' in frag):
                if all(32<=c<127 for c in frag):
