import sys
import binascii
import string

filename = '/home/ctfplayer/ctf_files/thoroughlyStripped'
FLAG_START = b'flag{'
FLAG_END = b'}'
FLAG_REV = b'}galf'

COMMON_XORS = [1, 2, 0x20, 0x80, 0xFF]
ROT_VALS = [13, 18, 47, 64]

# Load the file
with open(filename, 'rb') as f:
    data = f.read()

# Only nonprintable bytes
nonprintable = bytes([b for b in data if chr(b) not in string.printable])

found = []

# Try direct search in all data/nonprintable regions
for look in [data, nonprintable]:
    for idx in range(len(look)):
        # Forward direct
        if look[idx:idx+5] == FLAG_START:
            end_idx = look.find(FLAG_END, idx+5)
            if end_idx != -1:
                cand = look[idx:end_idx+1]
                found.append(('direct', idx, cand))
        # Reversed
        if look[idx:idx+5] == FLAG_REV:
            # reversed might be at the end
            found.append(('reverse', idx, look[idx:idx+5][::-1]))

# XOR decoding & search
for xorval in COMMON_XORS:
    xordata = bytes([b ^ xorval for b in data])
    for idx in range(len(xordata)):
        if xordata[idx:idx+5] == FLAG_START:
            end_idx = xordata.find(FLAG_END, idx+5)
            if end_idx != -1:
                cand = xordata[idx:end_idx+1]
                found.append((f'xor_{xorval}', idx, cand))
        if xordata[idx:idx+5] == FLAG_REV:
            found.append((f'xor_{xorval}_rev', idx, xordata[idx:idx+5][::-1]))

# ROT search
for rotval in ROT_VALS:
    def rot(val, amt):
        return ((val + amt) % 256)
    rotdata = bytes([rot(b, rotval) for b in data])
    for idx in range(len(rotdata)):
        if rotdata[idx:idx+5] == FLAG_START:
            end_idx = rotdata.find(FLAG_END, idx+5)
            if end_idx != -1:
                cand = rotdata[idx:end_idx+1]
                found.append((f'rot_{rotval}', idx, cand))
        if rotdata[idx:idx+5] == FLAG_REV:
            found.append((f'rot_{rotval}_rev', idx, rotdata[idx:idx+5][::-1]))

# Output candidates (as ASCII and hex)
for how, idx, cand in found:
    try:
        print(f'METHOD: {how}, OFFSET: {idx}, ASCII: {cand.decode(errors="replace")}, HEX: {binascii.hexlify(cand).decode()}')
    except:
        print(f'METHOD: {how}, OFFSET: {idx}, RAW: {cand}, HEX: {binascii.hexlify(cand).decode()}')
if not found:
    print('No flag-like patterns found.')
